-- Booking platform queue schema is deployed to Supabase project lmrhgnlmetbyfxdlwyyw.
-- Keep this file as the source-of-truth migration for the dedicated Booking repository.
create extension if not exists pgcrypto;
create table if not exists businesses(id uuid primary key default gen_random_uuid(),name text not null,timezone text not null default 'Asia/Kolkata',created_at timestamptz not null default now());
create table if not exists services(id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses(id) on delete cascade,name text not null,duration_minutes integer not null default 10 check(duration_minutes>0),active boolean not null default true);
create table if not exists queue_settings(business_id uuid primary key references businesses(id) on delete cascade,range_size integer not null default 10,app_slots_per_range integer not null default 1,reserved_positions integer[] not null default array[5],average_handling_minutes integer not null default 10,approach_notification_minutes integer not null default 15,cutoff_minutes integer not null default 0,updated_at timestamptz not null default now());
create table if not exists queue_sessions(id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses(id) on delete cascade,service_id uuid references services(id) on delete set null,session_date date not null,status text not null default 'OPEN' check(status in('OPEN','PAUSED','CLOSED')),next_number integer not null default 1,created_at timestamptz not null default now(),unique(business_id,session_date));
create table if not exists bookings(id uuid primary key default gen_random_uuid(),business_id uuid not null references businesses(id) on delete cascade,service_id uuid references services(id) on delete set null,customer_name text not null,customer_phone text,source text not null check(source in('APP','OFFLINE')),created_at timestamptz not null default now());
create table if not exists queue_entries(id uuid primary key default gen_random_uuid(),session_id uuid not null references queue_sessions(id) on delete cascade,booking_id uuid not null unique references bookings(id) on delete cascade,queue_number integer not null,source text not null check(source in('APP','OFFLINE')),status text not null default 'BOOKED',expected_minutes integer not null default 10,estimated_turn_at timestamptz,created_at timestamptz not null default now(),unique(session_id,queue_number));